action.command:
node -e "
const fs = require('fs');
const path = require('path');
const file = JSON.parse(fs.readFileSync('/dev/stdin','utf8')).file || '';
if (!file.includes('/i18n/messages/')) process.exit(0);
const dir = path.dirname(file);
const locales = ['en', 'te', 'hi'];
const messages = {};
let error = false;
for (const locale of locales) {
  const f = path.join(dir, locale + '.json');
  if (!fs.existsSync(f)) { process.stderr.write('MISSING: ' + f + ' does not exist\n'); error = true; continue; }
  try { messages[locale] = JSON.parse(fs.readFileSync(f, 'utf8')); } 
  catch(e) { process.stderr.write('PARSE ERROR in ' + f + ': ' + e.message + '\n'); error = true; }
}
function getKeys(obj, prefix) {
  return Object.entries(obj).flatMap(([k, v]) =>
    typeof v === 'object' && v !== null ? getKeys(v, prefix ? prefix+'.'+k : k) : [prefix ? prefix+'.'+k : k]
  );
}
if (!error && messages['en']) {
  const enKeys = new Set(getKeys(messages['en'], ''));
  for (const locale of ['te', 'hi']) {
    if (!messages[locale]) continue;
    const lKeys = new Set(getKeys(messages[locale], ''));
    const missing = [...enKeys].filter(k => !lKeys.has(k));
    const extra = [...lKeys].filter(k => !enKeys.has(k));
    if (missing.length) { process.stderr.write('MISSING keys in ' + locale + '.json: ' + missing.join(', ') + '\n'); error = true; }
    if (extra.length) { process.stderr.write('EXTRA keys in ' + locale + '.json (not in en.json): ' + extra.join(', ') + '\n'); error = true; }
  }
}
if (error) process.exit(2);
console.log('i18n key parity check passed for all three locales.');
"
